from sklearn.ensemble import (RandomForestClassifier, RandomForestRegressor, ExtraTreesClassifier,
    ExtraTreesRegressor, GradientBoostingClassifier, GradientBoostingRegressor, AdaBoostClassifier,
    AdaBoostRegressor, BaggingClassifier, BaggingRegressor, IsolationForest, VotingClassifier,
    VotingRegressor)

X, y = data(90, 5, 3)
Xt0, _ = data(20, 5, 3)
Xt = Xt0 + 0.37
yr = reg_target(X)
yb = np.where(y == 2, 1, y)
R: float = 1e-9
A: float = 1e-12

@test
def t_forests():
    m = RandomForestClassifier(n_estimators=6, random_state=0, oob_score=True).fit(X, y)
    assert close(m.predict_proba(Xt), rfc_proba, R, A) and close(m.feature_importances_, rfc_fi, R, A) and close([m.oob_score_], rfc_oob, R, A)
    m2 = RandomForestClassifier(n_estimators=4, random_state=3, class_weight="balanced_subsample", max_samples=0.6, max_depth=4).fit(X, y)
    assert close(m2.predict_proba(Xt), rfc2_proba, R, A)
    r = RandomForestRegressor(n_estimators=5, random_state=1, max_depth=5, oob_score=True).fit(X, yr)
    assert close(r.predict(Xt), rfr_pred, R, A) and close(r.feature_importances_, rfr_fi, R, A) and close([r.oob_score_], rfr_oob, R, A)
    e = ExtraTreesClassifier(n_estimators=5, random_state=2).fit(X, y)
    assert close(e.predict_proba(Xt), etc_proba, R, A) and close(e.feature_importances_, etc_fi, R, A)
    er = ExtraTreesRegressor(n_estimators=4, random_state=2, bootstrap=True, max_samples=0.5).fit(X, yr)
    assert close(er.predict(Xt), etr_pred, R, A)
    assert close(cross_val_score(RandomForestClassifier(n_estimators=5, random_state=0), X, y, cv=KFold(4)), cvs_rf, R, A)

@test
def t_gb():
    m = GradientBoostingClassifier(n_estimators=10, random_state=0, subsample=0.8, max_features=3).fit(X, yb)
    assert close(m.predict_proba(Xt), gbb_proba, R, A) and close(m.train_score_, gbb_train, R, A) and close(m.oob_scores_, gbb_oob, R, A)
    e = GradientBoostingClassifier(loss="exponential", n_estimators=8, random_state=1).fit(X, yb)
    assert close(e.decision_function(Xt), gbe_dec, R, A)
    mc = GradientBoostingClassifier(n_estimators=8, random_state=0, learning_rate=0.2).fit(X, y)
    assert close(mc.predict_proba(Xt), gbm_proba, R, A) and close(mc.feature_importances_, gbm_fi, R, A)
    st = [float(p[0]) for p in mc.staged_predict(Xt[:1])]
    assert close(st, gbm_staged, 0.0)
    r1 = GradientBoostingRegressor(loss="squared_error", n_estimators=10, random_state=1, subsample=0.7, max_depth=2).fit(X, yr)
    assert close(r1.predict(Xt), gbr_squared_error_pred, R, A) and close(r1.feature_importances_, gbr_squared_error_fi, R, A)
    r2 = GradientBoostingRegressor(loss="absolute_error", n_estimators=10, random_state=1, subsample=0.7, max_depth=2).fit(X, yr)
    assert close(r2.predict(Xt), gbr_absolute_error_pred, R, A) and close(r2.feature_importances_, gbr_absolute_error_fi, R, A)
    r3 = GradientBoostingRegressor(loss="huber", n_estimators=10, random_state=1, subsample=0.7, max_depth=2).fit(X, yr)
    assert close(r3.predict(Xt), gbr_huber_pred, R, A) and close(r3.feature_importances_, gbr_huber_fi, R, A)
    r4 = GradientBoostingRegressor(loss="quantile", n_estimators=10, random_state=1, subsample=0.7, max_depth=2).fit(X, yr)
    assert close(r4.predict(Xt), gbr_quantile_pred, R, A) and close(r4.feature_importances_, gbr_quantile_fi, R, A)

@test
def t_others():
    a = AdaBoostClassifier(n_estimators=10, random_state=0).fit(X, y)
    assert close(a.predict_proba(Xt), abc_proba, R, A) and close(a.estimator_weights_, abc_w, R, A)
    ar = AdaBoostRegressor(n_estimators=8, random_state=0, loss="square").fit(X, yr)
    assert close(ar.predict(Xt), abr_pred, R, A)
    b = BaggingClassifier(n_estimators=5, random_state=0, max_samples=0.7, max_features=0.8).fit(X, y)
    assert close(b.predict_proba(Xt), bgc_proba, R, A)
    br = BaggingRegressor(n_estimators=5, random_state=2, bootstrap_features=True).fit(X, yr)
    assert close(br.predict(Xt), bgr_pred, R, A)
    i1 = IsolationForest(n_estimators=10, random_state=0).fit(X)
    assert close(i1.score_samples(Xt), iso_score, R, A)
    i2 = IsolationForest(n_estimators=6, random_state=1, contamination=0.1, max_samples=40).fit(X)
    assert close(i2.decision_function(Xt), iso2_dec, R, A)
    v = VotingClassifier((("a", DecisionTreeClassifier(random_state=0, max_depth=3)), ("b", RandomForestClassifier(n_estimators=4, random_state=0))), voting="soft", weights=[1, 2]).fit(X, y)
    assert close(v.predict_proba(Xt), vc_proba, R, A)
    vr = VotingRegressor((("a", DecisionTreeRegressor(random_state=0, max_depth=3)), ("b", GradientBoostingRegressor(n_estimators=5, random_state=0)))).fit(X, yr)
    assert close(vr.predict(Xt), vr_pred, R, A)

t_forests()
t_gb()
t_others()
